'use client';

import { useCart } from '@/lib/useCart';
import { useShippingAddress } from '@/lib/useShippingAddress';
import { subtotal, total } from '@/lib/cart';
import { formatMoney } from '@/lib/money';
import { calculateTax } from '@/lib/tax';

function Row({ label, value }: { label: string; value: number }) {
  return (
    <div className="flex justify-between py-1">
      <span>{label}</span>
      <span>{formatMoney(value)}</span>
    </div>
  );
}

const SHIPPING = 5.99;

export default function Summary() {
  const cart = useCart();
  const address = useShippingAddress();
  const sub = subtotal(cart.items);
  const grand = total(cart.items, SHIPPING);

  return (
    <section aria-label="Order summary" className="rounded border p-4">
      <h2 className="mb-2 font-semibold">Summary</h2>
      <p className="text-sm text-gray-500">Shipping to {address.state}</p>
      <hr className="my-2" />
      <div className="space-y-1">
        <Row label="Subtotal" value={sub} />
        <Row label="Sales tax" value={calculateTax(cart.items, address.state)} />
        <Row label="Shipping" value={SHIPPING} />
        <Row label="Total" value={grand} />
      </div>
    </section>
  );
}

