import { db } from './db/client';

// The load balancer gives up after 2s, so the database gets 1s to answer.
export const DB_TIMEOUT_MS = 1000;

export async function withTimeout<T>(p: Promise<T>, ms: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(new Error(`timed out after ${ms}ms`)), ms);
  });
  try {
    return await Promise.race([p, timeout]);
  } finally {
    clearTimeout(timer);
  }
}

export async function checkDatabase(): Promise<boolean> {
  try {
    await withTimeout(db.$queryRaw`SELECT 1`, DB_TIMEOUT_MS);
    return true;
  } catch {
    return false;
  }
}

import { checkDatabase } from '@/lib/health';

export const dynamic = 'force-dynamic';

export async function GET() {
  const ok = await checkDatabase();
  return Response.json({ ok }, { status: ok ? 200 : 503 });
}

import { withTimeout } from './health';

jest.mock('./db/client', () => ({ db: {} }));

it('passes a fast result through', async () => {
  await expect(withTimeout(Promise.resolve('ok'), 50)).resolves.toBe('ok');
});

it('rejects when the check is too slow', async () => {
  const slow = new Promise((resolve) => setTimeout(resolve, 200));
  await expect(withTimeout(slow, 20)).rejects.toThrow('timed out after 20ms');
});
